CREATE TABLE "SchoolEvent" ("id" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"eventType" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),"audience" TEXT NOT NULL DEFAULT 'ALL',"location" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SchoolEvent_pkey" PRIMARY KEY("id"));CREATE INDEX "SchoolEvent_schoolId_startsAt_idx" ON "SchoolEvent"("schoolId","startsAt");ALTER TABLE "SchoolEvent" ADD CONSTRAINT "SchoolEvent_schoolId_fkey" FOREIGN KEY("schoolId") REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "Notification" ("id" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"recipientId" TEXT,"channel" TEXT NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"sentAt" TIMESTAMP(3),"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Notification_pkey" PRIMARY KEY("id"));CREATE INDEX "Notification_schoolId_recipientId_status_idx" ON "Notification"("schoolId","recipientId","status");ALTER TABLE "Notification" ADD CONSTRAINT "Notification_schoolId_fkey" FOREIGN KEY("schoolId") REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Notification" ADD CONSTRAINT "Notification_recipientId_fkey" FOREIGN KEY("recipientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"schoolId" TEXT,"actorId" TEXT,"method" TEXT NOT NULL,"path" TEXT NOT NULL,"action" TEXT NOT NULL,"entityType" TEXT,"entityId" TEXT,"metadata" JSONB,"ipAddress" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY("id"));CREATE INDEX "AuditLog_schoolId_createdAt_idx" ON "AuditLog"("schoolId","createdAt");CREATE INDEX "AuditLog_actorId_createdAt_idx" ON "AuditLog"("actorId","createdAt");ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_schoolId_fkey" FOREIGN KEY("schoolId") REFERENCES "School"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
